with tempfile.TemporaryDirectory() as d:
    d=Path(d)
    for name, content in sources.items():
        p=d/name; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(content)
    production=[root/'src/main/java/com/nexusrpg/world/tower/LargeTowerEncounter.java',root/'src/main/java/com/nexusrpg/mage/MageRegistration.java']
    if '--old-order' in sys.argv:
        # Recreate the pre-fix ordering in a disposable source copy.
        text=production[0].read_text()
        before='''MageRegistration.spawnTowerMage(world, bossFeet,
            mage -> mage.getEntityData().setInteger(STYLE, style + 1));
        if (boss == null) return false;'''
        after='''MageRegistration.spawnTowerMage(world, bossFeet);
        if (boss == null) return false;
        boss.getEntityData().setInteger(STYLE, style + 1);'''
        assert before in text
        old=d/'LargeTowerEncounter.java'; old.write_text(text.replace(before, after))
        production[0]=old
    home=os.environ.get('JAVA_HOME'); binpath=Path(home)/'bin' if home else Path('')
    javac=str(binpath/'javac') if home else 'javac'; java=str(binpath/'java') if home else 'java'
    subprocess.run([javac,'-source','8','-target','8','-d',str(d)]+[str(d/p) for p in sources]+list(map(str,production)),check=True)
    subprocess.run([java,'-cp',str(d),'TowerEncounterTest'],check=True)
